import numpy as np
mapa = np.array([[1,-1,2,4],[5,6,-7,8],[3,2,1,0],[-1,2,3,4]])
relu = np.maximum(0, mapa)
pool = np.zeros((2,2), dtype=int)
for i in range(2):
    for j in range(2):
        pool[i,j] = relu[2*i:2*i+2, 2*j:2*j+2].max()
fig, axs = plt.subplots(1, 3, figsize=(9.8, 4.2))
for ax, M, t, c in zip(axs, [mapa, relu, pool], ['mapa 4x4', 'sin negativos', 'solo el máximo'], ['coolwarm', 'YlGn', 'spring']):
    ax.imshow(M, cmap=c)
    for a in range(M.shape[0]):
        for b in range(M.shape[1]):
            ax.text(b, a, str(int(M[a,b])), ha='center', va='center', fontsize=23, fontweight='bold', color='#0A0A0F')
    ax.set_title(t, fontsize=19)
    ax.set_xticks([]); ax.set_yticks([])
